const partitionCache = new Map<string, string[]>();

export function findBestFuriganaPartition(kanjiString: string, readingString: string): string[] {
  const K = kanjiString.length;
  if (K === 0) return [];
  if (K === 1) return [readingString];

  const cacheKey = `${kanjiString}|${readingString}`;
  if (partitionCache.has(cacheKey)) {
    return partitionCache.get(cacheKey)!;
  }

  // 1. Check explicit compound overrides first
  if (COMPOUND_FURIGANA_PARTITIONS[kanjiString]) {
    const override = COMPOUND_FURIGANA_PARTITIONS[kanjiString];
    if (override.join('') === readingString) {
      partitionCache.set(cacheKey, override);
      return override;
    }
  }

  // Safety threshold to avoid exponential backtracking on long compounds
  if (K > 5) {
    const result: string[] = [];
    const partLen = Math.max(1, Math.round(readingString.length / K));
    for (let i = 0; i < K; i++) {
      if (i === K - 1) {
        result.push(readingString.slice(i * partLen));
      } else {
        result.push(readingString.slice(i * partLen, (i + 1) * partLen));
      }
    }
    partitionCache.set(cacheKey, result);
    return result;
  }

  // Helper to get common readings
  const getReadings = (char: string): string[] => {
    if (!/[\u4e00-\u9faf]/.test(char)) {
      return [char];
    }
    return KANJI_COMMON_READINGS[char] || [];
  };

  let bestPartition: string[] | null = null;
  let bestScore = -Infinity;

  function backtrack(charIndex: number, currentStrIndex: number, currentPartition: string[], currentScore: number) {
    if (charIndex === K) {
      if (currentStrIndex === readingString.length) {
        if (currentScore > bestScore) {
          bestScore = currentScore;
          bestPartition = [...currentPartition];
        }
      }
      return;
    }

    const remainingChars = K - charIndex;
    const maxLen = readingString.length - currentStrIndex - remainingChars + 1;

    for (let len = 1; len <= maxLen; len++) {
      const part = readingString.slice(currentStrIndex, currentStrIndex + len);
      const kanjiChar = kanjiString[charIndex];
      const isKanjiChar = /[\u4e00-\u9faf]/.test(kanjiChar);
      const knownReadings = getReadings(kanjiChar);

      let score = 0;
      if (!isKanjiChar) {
        if (part === kanjiChar) {
          score = 50;
        } else {
          score = -50;
        }
      } else {
        if (knownReadings.includes(part)) {
          score = 15;
        } else if (knownReadings.some(r => r.startsWith(part) || part.startsWith(r))) {
          score = 3;
        } else {
          if (len === 1 || len === 2) {
            score = 1;
          } else if (len === 3) {
            score = 0;
          } else {
            score = -5;
          }
        }
      }

      backtrack(
        charIndex + 1,
        currentStrIndex + len,
        [...currentPartition, part],
        currentScore + score
      );
    }
  }

  backtrack(0, 0, [], 0);

  let finalResult: string[];
  if (bestPartition) {
    finalResult = bestPartition;
  } else {
    // Fallback: split proportionally
    const result: string[] = [];
    const partLen = Math.max(1, Math.round(readingString.length / K));
    for (let i = 0; i < K; i++) {
      if (i === K - 1) {
        result.push(readingString.slice(i * partLen));
      } else {
        result.push(readingString.slice(i * partLen, (i + 1) * partLen));
      }
    }
    finalResult = result;
  }

  partitionCache.set(cacheKey, finalResult);
  return finalResult;
}

export interface TextToken {
  type: 'kanji' | 'kana';
  text: string;
  reading?: string;
}

export function tokenizeWithFurigana(kanjiString: string = '', readings: string[] = []): TextToken[] {
  const safeStr = kanjiString || '';
  const safeReadings = readings || [];
  // If the whole compound is a single unsplittable Jukujikun unit (e.g. 今日, 明日, 風邪)
  if (safeReadings.length === 1 && safeStr.length > 1) {
    return [{ type: 'kanji', text: safeStr, reading: safeReadings[0] }];
  }

  const tokens: TextToken[] = [];
  for (let i = 0; i < safeStr.length; i++) {
    const char = safeStr[i];
    const isKanji = /[\u4e00-\u9faf\u3400-\u4dbf]/.test(char);
    const reading = safeReadings[i] || '';
    
    if (isKanji) {
      tokens.push({ type: 'kanji', text: char, reading });
    } else {
      const lastToken = tokens[tokens.length - 1];
      if (lastToken && lastToken.type === 'kana') {
        lastToken.text = (lastToken.text || '') + char;
      } else {
        tokens.push({ type: 'kana', text: char });
      }
    }
  }
  return tokens;
}

export interface FuriganaPart {
  text: string;
  furigana?: string;
}

/**
 * Splits a word with Kanji and its reading into prefix/suffix Hiragana and core Kanji parts,
 * accurately handling internal okurigana so that Furigana is precisely aligned ONLY over the Kanji characters.
 */
export function alignWordFurigana(kanji: string, reading: string): FuriganaPart[] {
  if (!kanji || !reading) return [{ text: kanji || reading || '' }];
  if (kanji === reading) return [{ text: kanji }];

  const isKanjiChar = (char: string) => /[\u4e00-\u9faf\u3400-\u4dbf]/.test(char);
  const hasKanji = kanji.split('').some(isKanjiChar);
  if (!hasKanji) {
    return [{ text: kanji }];
  }

  // 1. Handle parenthetical options like （...） or (...) in both kanji and reading
  const hasBrackets = (kanji.includes('（') || kanji.includes('(')) && (reading.includes('（') || reading.includes('('));
  if (hasBrackets) {
    const kParts = kanji.split(/([（\(\）\)])/);
    const rParts = reading.split(/([（\(\）\)])/);
    if (kParts.length === rParts.length) {
      const res: FuriganaPart[] = [];
      for (let i = 0; i < kParts.length; i++) {
        const kp = kParts[i];
        const rp = rParts[i];
        if (kp === '（' || kp === '(' || kp === '）' || kp === ')') {
          res.push({ text: kp });
        } else if (kp) {
          res.push(...alignWordFurigana(kp.trim(), (rp || '').trim()));
        }
      }
      return res;
    }
  }

  // 2. Handle slashes ／ or /
  const hasSlashes = (kanji.includes('／') || kanji.includes('/')) && (reading.includes('／') || reading.includes('/'));
  if (hasSlashes) {
    const slashChar = kanji.includes('／') ? '／' : '/';
    const kParts = kanji.split(slashChar);
    const rParts = reading.split(slashChar);
    if (kParts.length === rParts.length) {
      const res: FuriganaPart[] = [];
      for (let i = 0; i < kParts.length; i++) {
        if (i > 0) res.push({ text: slashChar });
        res.push(...alignWordFurigana(kParts[i].trim(), (rParts[i] || '').trim()));
      }
      return res;
    }
  }

  let prefixLen = 0;
  while (
    prefixLen < kanji.length &&
    prefixLen < reading.length &&
    kanji[prefixLen] === reading[prefixLen] &&
    !isKanjiChar(kanji[prefixLen])
  ) {
    prefixLen++;
  }

  let suffixLen = 0;
  while (
    suffixLen < kanji.length - prefixLen &&
    suffixLen < reading.length - prefixLen &&
    kanji[kanji.length - 1 - suffixLen] === reading[reading.length - 1 - suffixLen] &&
    !isKanjiChar(kanji[kanji.length - 1 - suffixLen])
  ) {
    suffixLen++;
  }

  const result: FuriganaPart[] = [];

  if (prefixLen > 0) {
    result.push({ text: kanji.slice(0, prefixLen) });
  }

  const midKanji = kanji.slice(prefixLen, kanji.length - suffixLen);
  let midReading = reading.slice(prefixLen, reading.length - suffixLen);

  if (midReading.split('').some(isKanjiChar)) {
    if (midKanji === '一番') midReading = 'いちばん';
    else if (midKanji === '一つ') midReading = 'ひとつ';
    else if (midKanji === '二つ') midReading = 'ふたつ';
    else if (midKanji === '三つ') midReading = 'みっつ';
    else if (midKanji === '四つ') midReading = 'よっつ';
    else if (midKanji === '五つ') midReading = 'いつつ';
    else if (midKanji === '六つ') midReading = 'むっつ';
    else if (midKanji === '七つ') midReading = 'ななつ';
    else if (midKanji === '八つ') midReading = 'やっつ';
    else if (midKanji === '九つ') midReading = 'ここのつ';
    else if (midKanji === '十') midReading = 'とお';
    else {
      midReading = midReading.replace(/[\u4e00-\u9faf\u3400-\u4dbf]/g, '');
    }
  }

  if (midKanji.length > 0) {
    // Check if midKanji has internal non-kanji characters (e.g. 話し合う -> 話 + し + 合)
    const segments: { text: string; isKanji: boolean }[] = [];
    let cur = '';
    let curIsKanji = isKanjiChar(midKanji[0]);
    for (let i = 0; i < midKanji.length; i++) {
      const isK = isKanjiChar(midKanji[i]);
      if (isK === curIsKanji) {
        cur += midKanji[i];
      } else {
        segments.push({ text: cur, isKanji: curIsKanji });
        cur = midKanji[i];
        curIsKanji = isK;
      }
    }
    if (cur) segments.push({ text: cur, isKanji: curIsKanji });

    if (segments.length > 1 && segments.some(s => !s.isKanji)) {
      // Split intermediate segments based on kana delimiters
      const intermediateParts: FuriganaPart[] = [];
      let rIdx = 0;
      let matchedAll = true;

      for (let sIdx = 0; sIdx < segments.length; sIdx++) {
        const seg = segments[sIdx];
        if (!seg || !seg.text) continue;
        if (!seg.isKanji) {
          const nextRIdx = midReading.indexOf(seg.text, rIdx);
          if (nextRIdx === -1) {
            matchedAll = false;
            break;
          }
          if (sIdx > 0 && segments[sIdx - 1]?.isKanji) {
            const kanjiSeg = segments[sIdx - 1];
            const furiganaPart = midReading.slice(rIdx, nextRIdx);
            intermediateParts.push({ text: kanjiSeg?.text || '', furigana: furiganaPart });
          }
          intermediateParts.push({ text: seg.text });
          rIdx = nextRIdx + seg.text.length;
        } else if (sIdx === segments.length - 1) {
          const furiganaPart = midReading.slice(rIdx);
          intermediateParts.push({ text: seg.text, furigana: furiganaPart });
        }
      }

      if (matchedAll && intermediateParts.length > 0) {
        result.push(...intermediateParts);
      } else {
        result.push({ text: midKanji, furigana: midReading });
      }
    } else {
      result.push({ text: midKanji, furigana: midReading });
    }
  }

  if (suffixLen > 0) {
    result.push({ text: kanji.slice(kanji.length - suffixLen) });
  }

  return result;
}

