export function ensureVocabExample(item: { 
  kanji?: string | null; 
  hiragana?: string | null; 
  meaning?: string; 
  exampleSentence?: string; 
  exampleTranslation?: string;
  exampleFuriganaHtml?: string;
  englishExampleTranslation?: string;
  level?: string;
  lessonId?: string;
  lessonName?: string;
}): { exampleSentence: string; exampleTranslation: string; exampleFuriganaHtml?: string; englishExampleTranslation?: string } {
  // 1. Return existing exampleSentence if present
  if (item.exampleSentence && item.exampleSentence.trim().length >= 2) {
    return {
      exampleSentence: item.exampleSentence.trim(),
      exampleTranslation: item.exampleTranslation ? item.exampleTranslation.trim() : '',
      exampleFuriganaHtml: item.exampleFuriganaHtml,
      englishExampleTranslation: item.englishExampleTranslation
    };
  }

  // 2. Clean raw word and generate simple, clean fallback
  let raw = (item.kanji || item.hiragana || '').trim();
  raw = cleanVocabSymbols(raw);
  if (raw.includes('、') || raw.includes(',')) {
    const parts = raw.split(/[、,]/).map(p => p.trim()).filter(Boolean);
    const polite = parts.find(p => p.endsWith('ます') || p.endsWith('です'));
    raw = polite || parts[0] || raw;
  }

  const word = raw || '日本語';
  const meaning = item.meaning || word;
  return {
    exampleSentence: `${word}を使います。`,
    exampleTranslation: `Sử dụng ${meaning}.`,
    exampleFuriganaHtml: item.exampleFuriganaHtml,
    englishExampleTranslation: item.englishExampleTranslation
  };
}

// Pre-compiled and sorted base keywords from COMMON_KANJI_READINGS & All Vocab Datasets
const baseKeywordsMap: Record<string, string> = { ...COMMON_KANJI_READINGS };

// Add all standard vocab datasets (N5, N4, Tango N4, N3, N2, N1) and extract verb/adjective stems & inflections
const staticVocabSources = [
  ...(Array.isArray(MINNA_N5_VOCABULARY) ? MINNA_N5_VOCABULARY : []),
  ...(Array.isArray(MINNA_N4_VOCABULARY) ? MINNA_N4_VOCABULARY : []),
  ...(Array.isArray(TANGO_N4_VOCABULARY) ? TANGO_N4_VOCABULARY : []),
  ...(Array.isArray(ADVANCED_VOCABULARY) ? ADVANCED_VOCABULARY : [])
];

function registerKeyword(k: string, r: string) {
  if (!k || !r || !/[\u4e00-\u9faf\u3400-\u4dbf]/.test(k)) return;
  if (!baseKeywordsMap[k]) {
    baseKeywordsMap[k] = r;
  }
}

staticVocabSources.forEach((v: any) => {
  const originalKanji = v.kanji || v.word || '';
  const isTildeBound = /[～~〜〰]/.test(originalKanji);
  const rawKanji = cleanVocabSymbols(originalKanji);
  const rawReading = cleanVocabSymbols(v.reading || v.hiragana || '');
  if (!rawKanji || !rawReading) return;

  const kanjiVariants = rawKanji.split(/[、,／/]/).map((k: string) => k.trim()).filter(Boolean);
  const readingVariants = rawReading.split(/[、,／/]/).map((r: string) => r.trim()).filter(Boolean);

  kanjiVariants.forEach((kanji: string, idx: number) => {
    let reading = readingVariants[idx] || readingVariants[0] || rawReading;
    if (kanji && reading) {
      // Do not allow bound suffixes like ～人 or ～時 to overwrite standalone single Kanji words
      if (isTildeBound && kanji.length === 1) return;

      registerKeyword(kanji, reading);

      // Masu-form verbs (e.g. 会います -> あいます, 食べます -> たべます)
      if (kanji.endsWith('ます') && reading.endsWith('ます')) {
        const kStem = kanji.slice(0, -2);
        const rStem = reading.slice(0, -2);
        registerKeyword(kStem + 'ました', rStem + 'ました');
        registerKeyword(kStem + 'ません', rStem + 'ません');
        registerKeyword(kStem + 'ませんでした', rStem + 'ませんでした');
        registerKeyword(kStem + 'たい', rStem + 'たい');
        registerKeyword(kStem + 'たくない', rStem + 'たくない');
        registerKeyword(kStem + 'ましょう', rStem + 'ましょう');
        registerKeyword(kStem + 'ながら', rStem + 'ながら');
        registerKeyword(kStem + 'なさい', rStem + 'なさい');
        registerKeyword(kStem + 'たくありません', rStem + 'たくありません');
      }

      // I-adjectives (e.g. 高い -> たかい)
      if (kanji.endsWith('い') && reading.endsWith('い') && kanji.length > 1) {
        const kStem = kanji.slice(0, -1);
        const rStem = reading.slice(0, -1);
        registerKeyword(kStem + 'かった', rStem + 'かった');
        registerKeyword(kStem + 'くない', rStem + 'くない');
        registerKeyword(kStem + 'くなかった', rStem + 'くなかった');
        registerKeyword(kStem + 'く', rStem + 'く');
        registerKeyword(kStem + 'くて', rStem + 'くて');
      }

      // Honorific prefix extraction (e.g. お仕事 -> 仕事, ご家族 -> 家族)
      if (((kanji.startsWith('お') && reading.startsWith('お')) || (kanji.startsWith('ご') && reading.startsWith('ご'))) && kanji.length > 2) {
        const stemK = kanji.slice(1);
        const stemR = reading.slice(1);
        registerKeyword(stemK, stemR);
      }

      // Na-adjective stem extraction (e.g. 有名な -> 有名)
      if (kanji.endsWith('な') && reading.endsWith('な') && kanji.length > 2) {
        const stemK = kanji.slice(0, -1);
        const stemR = reading.slice(0, -1);
        registerKeyword(stemK, stemR);
      }

      // Suffix stem extraction
      let kEnd = kanji.length;
      let rEnd = reading.length;
      while (kEnd > 0 && rEnd > 0 && kanji[kEnd - 1] === reading[rEnd - 1]) {
        kEnd--;
        rEnd--;
      }
      if (kEnd > 0 && rEnd > 0 && kEnd < kanji.length) {
        const kanjiStem = kanji.substring(0, kEnd);
        const readingStem = reading.substring(0, rEnd);
        const isCorrupt = kanjiStem.includes("を") || kanjiStem.includes("に") || kanjiStem.includes("が") || kanjiStem.includes("へ") || kanjiStem.includes("で");
        if (!isCorrupt) {
          registerKeyword(kanjiStem, readingStem);
        }
      }
    }
  });
});

export const PRECOMPILED_BASE_KEYWORDS: { kanji: string; hiragana: string }[] = Object.entries(baseKeywordsMap)
  .filter(([kanji]) => kanji && /[\u4e00-\u9faf\u3400-\u4dbf]/.test(kanji))
  .map(([kanji, hiragana]) => ({ kanji, hiragana }))
  .sort((a, b) => b.kanji.length - a.kanji.length);

// Fast in-memory cache for sentence furigana parts
const sentenceFuriganaCache = new Map<string, FuriganaPart[]>();
const MAX_CACHE_SIZE = 1000;

export function getSentenceFuriganaParts(
  sentence: string,
  currentItem: { kanji?: string | null; hiragana?: string; word?: string } = {},
  vocabData: any[] = []
): FuriganaPart[] {
  if (!sentence) return [];

  const cacheKey = `${sentence}__${currentItem.kanji || ''}__${currentItem.hiragana || ''}`;
  const cached = sentenceFuriganaCache.get(cacheKey);
  if (cached) return cached;

  // Check if the sentence has explicit HTML <ruby> or bracket markdown furigana tags
  const hasRuby = /<ruby[\s\S]*?<\/ruby>/i.test(sentence);
  const hasMdParen = /\[([^\]]+)\]\(([^)]+)\)/.test(sentence);
  const hasKanjiBracket = /([\u4e00-\u9faf\u3400-\u4dbf]+)\[([\u3040-\u30ff]+)\]/.test(sentence);
  const hasBracketPair = /\[([^\]]+)\]\[([^\]]+)\]/.test(sentence);
  const hasCurly = /\{([^|]+)\|([^}]+)\}/.test(sentence);

  if (hasRuby || hasMdParen || hasKanjiBracket || hasBracketPair || hasCurly) {
    const rawExplicitParts: { text: string; furigana?: string }[] = [];
    const regex = /<ruby>(.*?)<rt>(.*?)<\/rt>(?:<rp>.*?<\/rp>)*<\/ruby>|\[([^\]]+)\]\(([^)]+)\)|\[([^\]]+)\]\[([^\]]+)\]|([\u4e00-\u9faf\u3400-\u4dbf]+)\[([\u3040-\u30ff]+)\]|\{([^|]+)\|([^}]+)\}/gi;
    let lastIdx = 0;
    let match: RegExpExecArray | null;

    while ((match = regex.exec(sentence)) !== null) {
      if (match.index > lastIdx) {
        const between = sentence.slice(lastIdx, match.index);
        if (between) {
          rawExplicitParts.push(...getSentenceFuriganaParts(between, currentItem, vocabData));
        }
      }

      let k = '';
      let f = '';
      if (match[1] !== undefined && match[2] !== undefined) {
        // HTML <ruby>
        k = match[1].replace(/<[^>]+>/g, '').trim();
        f = match[2].trim();
      } else if (match[3] !== undefined && match[4] !== undefined) {
        // [kanji](reading)
        k = match[3].trim();
        f = match[4].trim();
      } else if (match[5] !== undefined && match[6] !== undefined) {
        // [kanji][reading]
        k = match[5].trim();
        f = match[6].trim();
      } else if (match[7] !== undefined && match[8] !== undefined) {
        // kanji[reading]
        k = match[7].trim();
        f = match[8].trim();
      } else if (match[9] !== undefined && match[10] !== undefined) {
        // {kanji|reading}
        k = match[9].trim();
        f = match[10].trim();
      }

      if (k) {
        rawExplicitParts.push({ text: k, furigana: f || undefined });
      }
      lastIdx = regex.lastIndex;
    }

    if (lastIdx < sentence.length) {
      const remainder = sentence.slice(lastIdx);
      if (remainder) {
        rawExplicitParts.push(...getSentenceFuriganaParts(remainder, currentItem, vocabData));
      }
    }

    if (sentenceFuriganaCache.size >= MAX_CACHE_SIZE) {
      const firstKey = sentenceFuriganaCache.keys().next().value;
      if (firstKey) sentenceFuriganaCache.delete(firstKey);
    }
    sentenceFuriganaCache.set(cacheKey, rawExplicitParts);
    return rawExplicitParts;
  }

  const keywords: { kanji: string; hiragana: string }[] = [];

  // 1. Current item full keyword and sub-variants
  if (currentItem.kanji && currentItem.hiragana) {
    const rawKanji = cleanVocabSymbols(currentItem.kanji);
    const rawReading = cleanVocabSymbols(currentItem.hiragana);
    const kanjiVariants = rawKanji.split(/[、,／/]/).map(k => k.trim()).filter(Boolean);
    const readingVariants = rawReading.split(/[、,／/]/).map(r => r.trim()).filter(Boolean);

    kanjiVariants.forEach((kanji, idx) => {
      const reading = readingVariants[idx] || readingVariants[0] || rawReading;
      if (kanji && reading) {
        const isMismatchedParticle = (kanji.includes("を") && !reading.includes("を")) || (kanji.includes("に") && !reading.includes("に")) || (kanji.includes("が") && !reading.includes("が"));
        if (!isMismatchedParticle) {
          keywords.push({ kanji, hiragana: reading });
        }

        // Derive stem if verb/adjective (e.g. 探します/さがします -> stem 探/さが)
        let kEnd = kanji.length;
        let rEnd = reading.length;
        while (kEnd > 0 && rEnd > 0 && kanji[kEnd - 1] === reading[rEnd - 1]) {
          kEnd--;
          rEnd--;
        }
        if (kEnd > 0 && rEnd > 0 && kEnd < kanji.length) {
          const kanjiStem = kanji.substring(0, kEnd);
          const readingStem = reading.substring(0, rEnd);
          const isCorrupt = kanjiStem.includes("を") || kanjiStem.includes("に") || kanjiStem.includes("が") || kanjiStem.includes("へ") || kanjiStem.includes("で");
          if (!isCorrupt) {
            keywords.push({ kanji: kanjiStem, hiragana: readingStem });
          }
        }
      }
    });
  }

  // 2. Add precompiled base compound keywords
  keywords.push(...PRECOMPILED_BASE_KEYWORDS);

  // 3. Add vocabData keywords and derived stems if kanji exists in target sentence
  if (Array.isArray(vocabData) && vocabData.length > 0) {
    for (let i = 0; i < vocabData.length; i++) {
      const v = vocabData[i];
      if (v && v.kanji && (v.reading || v.hiragana) && sentence.includes(v.kanji)) {
        const r = v.reading || v.hiragana || '';
        const isMismatchedParticle = (v.kanji.includes("を") && !r.includes("を")) || (v.kanji.includes("に") && !r.includes("に")) || (v.kanji.includes("が") && !r.includes("が"));
        if (!isMismatchedParticle) {
          keywords.push({ kanji: v.kanji, hiragana: r });
        }

        // Stem extraction
        let kEnd = v.kanji.length;
        let rEnd = r.length;
        while (kEnd > 0 && rEnd > 0 && v.kanji[kEnd - 1] === r[rEnd - 1]) {
          kEnd--;
          rEnd--;
        }
        if (kEnd > 0 && rEnd > 0 && kEnd < v.kanji.length) {
          const kanjiStem = v.kanji.substring(0, kEnd);
          const isCorrupt = kanjiStem.includes("を") || kanjiStem.includes("に") || kanjiStem.includes("が") || kanjiStem.includes("へ") || kanjiStem.includes("で");
          if (!isCorrupt) {
            keywords.push({ kanji: kanjiStem, hiragana: r.substring(0, rEnd) });
          }
        }
      }
    }
  }

  // Sort keywords by kanji length descending
  const sortedKeywords = keywords
    .filter(k => k.kanji && k.kanji.length > 0)
    .sort((a, b) => b.kanji.length - a.kanji.length);

  const parts: FuriganaPart[] = [];
  let currentIndex = 0;
  const kanjiRegex = /[\u4e00-\u9faf\u3400-\u4dbf]/;

  while (currentIndex < sentence.length) {
    let matched = false;

    for (let i = 0; i < sortedKeywords.length; i++) {
      const kw = sortedKeywords[i];
      if (sentence.startsWith(kw.kanji, currentIndex)) {
        parts.push({
          text: kw.kanji,
          furigana: kw.hiragana
        });
        currentIndex += kw.kanji.length;
        matched = true;
        break;
      }
    }

    if (!matched) {
      const char = sentence[currentIndex];
      // If char is Kanji and not matched yet, check single Kanji fallback
      if (kanjiRegex.test(char)) {
        let fallbackReading = SINGLE_KANJI_READINGS[char] || '';
        if (!fallbackReading && KANJI_DICTIONARY && KANJI_DICTIONARY[char]) {
          const info = KANJI_DICTIONARY[char];
          const kun = info.kunyomi ? info.kunyomi.split(/[,、\s]/)[0].replace(/[.-]/g, '') : '';
          const on = info.onyomi ? info.onyomi.split(/[,、\s]/)[0].replace(/[.-]/g, '') : '';
          fallbackReading = kun || (on ? katakanaToHiragana(on) : '');
        }
        parts.push({
          text: char,
          furigana: fallbackReading || undefined
        });
      } else {
        parts.push({ text: char });
      }
      currentIndex++;
    }
  }

  // Merge adjacent parts that do not have furigana to keep things clean
  const mergedParts: FuriganaPart[] = [];
  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];
    if (!part || !part.text) continue; // Defensive check
    if (mergedParts.length > 0 && !mergedParts[mergedParts.length - 1]?.furigana && !part.furigana) {
      const prev = mergedParts[mergedParts.length - 1];
      if (prev) {
        prev.text = (prev.text || '') + (part.text || '');
      }
    } else {
      mergedParts.push({ text: part.text || '', furigana: part.furigana });
    }
  }

  // Maintain cache size bound
  if (sentenceFuriganaCache.size >= MAX_CACHE_SIZE) {
    const firstKey = sentenceFuriganaCache.keys().next().value;
    if (firstKey) sentenceFuriganaCache.delete(firstKey);
  }
  sentenceFuriganaCache.set(cacheKey, mergedParts);

  return mergedParts;
}

/**
 * Checks if a string contains any Kanji characters
 */
export function hasKanji(text: string): boolean {
  if (!text) return false;
  return /[\u4e00-\u9faf\u3400-\u4dbf]/.test(text);
}

/**
 * Converts a Japanese sentence to full Hiragana/Furigana reading string
 */
export function getSentenceHiraganaReading(
  sentence: string,
  currentItem: { kanji?: string | null; hiragana?: string; word?: string } = {},
  vocabData: any[] = []
): string {
  if (!sentence) return '';
  const parts = getSentenceFuriganaParts(sentence, currentItem, vocabData);
  return (parts || []).map(p => (p ? (p.furigana || p.text || '') : '')).join('');
}

/**
 * Extracts all unique Kanji characters from a string in order of appearance
 */
export function extractKanjiList(text: string): string[] {
  if (!text) return [];
  const matches = text.match(/[\u4e00-\u9faf\u3400-\u4dbf]/g);
  if (!matches) return [];
  return Array.from(new Set(matches));
}

/**
 * Removes all bracket symbols ([], ［］, (), （）, {}, ＜＞, 「」) and tildes (~, ～, 〜, 〰)
 * from Japanese vocabulary strings (hiragana, kanji, romaji) to ensure clean display and smooth typing practice.
 */
/**
 * Intelligently cleans raw Japanese vocabulary strings by parsing out bracketed collocations,
 * polite variants, and honorific brackets to ensure clean, accurate display and audio pronunciation.
 */
export function cleanVocabSymbols(str: string): string {
  if (!str) return '';
  let text = str.trim();

  // Pattern 1: Collocations with tildes inside brackets, e.g. "吸います［たばこを～］", "吸います〈〜〉" -> "吸います"
  const colMatch = text.match(/^([^［\[（(「〈《〔【〖『]+)[［\[（(「〈《〔【〖『]([^］\]））」〉》〕】〗』]*[～~〜〰][^］\]））」〉》〕】〗』]*)[］\]））」〉》〕】〗』]/);
  if (colMatch) {
    text = colMatch[1].trim();
  }

  // Pattern 2: Optional honorific prefix [お], [ご], 〈お〉, etc., e.g. "［お］土産" -> "お土産", "〈お〉金" -> "お金"
  text = text.replace(/[［\[「〈《〔【〖『]お[］\]」〉》〕】〗』]/g, 'お').replace(/[［\[「〈《〔【〖『]ご[］\]」〉》〕】〗』]/g, 'ご');

  // Pattern 3: Brackets around complete polite phrases, e.g. "［どうぞ］よろしく［お願いします］" -> "どうぞよろしくお願いします"
  text = text.replace(/[［\[「〈《〔【〖『](どうぞ|ご|お|どうも)[］\]」〉》〕】〗』]/g, '$1');
  text = text.replace(/[［\[「〈《〔【〖『](お願いします|ございます|ください)[］\]」〉》〕】〗』]/g, '$1');

  // Pattern 4: Alternative/polite forms, suru notation or readings in brackets:
  // e.g. "入学〈する〉" -> "入学", "ねぼう〈する〉" -> "ねぼう", "あの 人（あの 方）" -> "あの人", "大丈夫「な」" -> "大丈夫"
  const parenMatch = text.match(/^([^（(［\[「〈《〔【〖『]+)[（(［\[「〈《〔【〖『]([^）)］\]」〉》〕】〗』]+)[）)］\]」〉》〕】〗』]/);
  if (parenMatch) {
    text = parenMatch[1].trim();
  }

  // Pattern 5: Slash-separated words, take the first primary word: e.g. "IMC／パワー電気／ブラジルエアー" -> "IMC"
  if (text.includes('／') || text.includes('/')) {
    const parts = text.split(/[／\/]/).map(s => s.trim()).filter(Boolean);
    if (parts.length > 0) {
      text = parts[0];
    }
  }

  // Strip remaining solitary bracket markers, angle brackets, or stray tildes
  let cleaned = text.replace(/[\[\]［］()（）{}＜＞<>「」〈〉《》〔〕【】〖〗『』~～〜〰]/g, '');
  cleaned = cleaned.replace(/^ー/, '');
  // Collapse spaces between Japanese characters (e.g. "あの 人" -> "あの人")
  cleaned = cleaned.replace(/([\u3040-\u30ff\u4e00-\u9faf])\s+([\u3040-\u30ff\u4e00-\u9faf])/g, '$1$2');
  return cleaned.replace(/\s+/g, ' ').trim();
}

/**
 * Sanitizes a vocabulary item object by cleaning Japanese fields and fixing common scraped data errors.
 */
export function sanitizeVocabItem<T extends Record<string, any>>(item: T): T {
  if (!item) return item;

  let kanji = item.kanji ? cleanVocabSymbols(item.kanji) : item.kanji;
  let hiragana = item.hiragana ? cleanVocabSymbols(item.hiragana) : (item.reading ? cleanVocabSymbols(item.reading) : item.hiragana);
  let romaji = item.romaji ? cleanVocabSymbols(item.romaji) : item.romaji;
  let reading = item.reading ? cleanVocabSymbols(item.reading) : hiragana;
  let word = item.word ? cleanVocabSymbols(item.word) : kanji || hiragana;
  let meaning = item.meaning || '';

  // Fix specific textbook/scraped mistranslations
  if ((kanji === '先生' || word === '先生') && (meaning === 'bác sĩ' || meaning.startsWith('bác sĩ'))) {
    meaning = 'Thầy cô giáo, giáo viên (tiên sinh)';
  }
  if ((kanji === 'あの人' || word === 'あの人') && (meaning.includes('người kia') || meaning.includes('anh ấy'))) {
    meaning = 'Người kia, người đó (anh ấy, chị ấy)';
  }
  if ((kanji === 'だれ' || word === 'だれ') && meaning.includes('ai')) {
    meaning = 'Ai, người nào';
  }

  return {
    ...item,
    hiragana,
    kanji,
    romaji,
    reading,
    word,
    meaning
  };
}

/**
 * Converts Katakana characters in a string to Hiragana
 */
export function katakanaToHiragana(str: string): string {
  if (!str) return '';
  return str.replace(/[\u30a1-\u30f6]/g, (match) =>
    String.fromCharCode(match.charCodeAt(0) - 0x60)
  );
}

/**
 * Converts Hiragana characters in a string to Katakana
 */
export function hiraganaToKatakana(str: string): string {
  if (!str) return '';
  return str.replace(/[\u3041-\u3096]/g, (match) =>
    String.fromCharCode(match.charCodeAt(0) + 0x60)
  );
}

/**
 * Checks if a string contains any Katakana characters
 */
export function isKatakana(str: string): boolean {
  if (!str) return false;
  return /[\u30a1-\u30f6]/.test(str);
}



/**
 * Normalizes Japanese long vowels (e.g. おお/おう -> おー, ああ -> あー)
 */
export function normalizeLongVowels(str: string): string {
  if (!str) return '';
  return str
    .replace(/(あ)あ/g, '$1ー')
    .replace(/(い)い/g, '$1ー')
    .replace(/(う)う/g, '$1ー')
    .replace(/(え)[えい]/g, '$1ー')
    .replace(/(お)[おう]/g, '$1ー');
}


